import { Readable } from 'node:stream'

/**
 * A running Studio HTTP server.
 */
export interface StudioServer {
  /**
   * Shuts down the server and stops accepting new connections.
   */
  close(): void
}

export interface StartStudioServerOptions {
  /**
   * Handles an incoming request and produces the response to send back.
   */
  handler: (request: Request) => Response | Promise<Response>

  /**
   * Invoked once the server is ready to accept connections.
   */
  onListen: () => void

  /**
   * The port to listen on.
   */
  port: number
}

/**
 * Starts an HTTP server that delegates incoming requests to `handler`.
 *
 * `GET` requests are answered with the handler's response (status and body are
 * streamed back to the client). `HEAD` requests reuse the status of the
 * equivalent `GET` response but send an empty body. When `handler` throws, the
 * server responds with a `500` whose body is the error message.
 */
export function startStudioServer({ handler, onListen, port }: StartStudioServerOptions): StudioServer {
  const server = createServer((req, res) => {
    void handleRequest(handler, req, res)
  })

  server.listen(port, onListen)

  return {
    close() {
      server.close()
    },
  }
}

async function handleRequest(
  handler: StartStudioServerOptions['handler'],
  req: IncomingMessage,
  res: ServerResponse,
): Promise<void> {
  const method = req.method ?? 'GET'
  const isHead = method === 'HEAD'

  let response: Response

  try {
    response = await handler(toWebRequest(req, isHead ? 'GET' : method))
  } catch (error) {
    console.error('[Prisma Studio]', error)

    res.statusCode = 500
    res.setHeader('access-control-allow-origin', '*')
    res.setHeader('content-type', 'text/plain; charset=utf-8')
    res.end(error instanceof Error ? error.message : String(error))
    return
  }

  res.statusCode = response.status

  response.headers.forEach((value, key) => {
    res.setHeader(key, value)
  })

  if (isHead || response.body === null) {
    res.end()
    return
  }

  Readable.fromWeb(response.body as Parameters<typeof Readable.fromWeb>[0]).pipe(res)
}

function toWebRequest(req: IncomingMessage, method: string): Request {
  const host = req.headers.host ?? 'localhost'
  const url = `http://${host}${req.url ?? '/'}`

  const headers = new Headers()

  for (const [name, value] of Object.entries(req.headers)) {
    if (Array.isArray(value)) {
      for (const item of value) {
        headers.append(name, item)
      }
    } else if (value !== undefined) {
      headers.set(name, value)
    }
  }

  const hasBody = method !== 'GET' && method !== 'HEAD'

  return new Request(url, {
    method,
    headers,
    body: hasBody ? (Readable.toWeb(req) as ReadableStream<Uint8Array>) : undefined,
    ...(hasBody ? { duplex: 'half' } : {}),
  } as RequestInit)
}
